    /** [id]'s plan, or null for a street the table does not place. */
    fun planFor(id: String): SceneObjectCatalog.StreetPlan? {
        val x = SHOP_X[id] ?: return null
        return SceneObjectCatalog.StreetPlan(x, MOVED_INDEX.getValue(id), MOVED_X.getValue(id))
    }
